Here is the problem description:
<problem_description>
Mr. Chanek has an integer represented by a string $$$s$$$. Zero or more digits have been erased and are denoted by the character _. There are also zero or more digits marked by the character X, meaning they're the same digit.Mr. Chanek wants to count the number of possible integer $$$s$$$, where $$$s$$$ is divisible by $$$25$$$. Of course, $$$s$$$ must not contain any leading zero. He can replace the character _ with any digit. He can also replace the character X with any digit, but it must be the same for every character X.As a note, a leading zero is any 0 digit that comes before the first nonzero digit in a number string in positional notation. For example, 0025 has two leading zeroes. An exception is the integer zero, (0 has no leading zero, but 0000 has three leading zeroes).
</problem_description>

Here is the Java 11 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;
import java.util.function.*;

public final class Solution {

  static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
  static BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

  static class Rec {
    int a, b;
    long c;
    Rec(int a, int b, long c) { this.a = a; this.b = b; this.c = c; }
  }

  static class Pair<F, S> {
    F a; S b;
    Pair(F a, S b) { this.a = a; this.b = b; }
  }

  static class AscendingComparator implements Comparator<Pair<Integer, Integer>> {
    public int compare(Pair<Integer, Integer> p1, Pair<Integer, Integer> p2) {
      return Integer.compare(p1.a, p2.a);
    }
  }

  static int modAdd(int a, int b, int mod) {
    return ((a % mod) + (b % mod)) % mod;
  }

  static int modSub(int a, int b, int mod) {
    return (int) (((a % mod) - (b % mod) + mod) % mod);
  }

  static int modMul(int a, int b, int mod) {
    return (int) (((long)(a % mod) * (b % mod)) % mod);
  }

  static int modPow(int base, int exp, int mod) {
    int res = 1;
    base %= mod;
    while (exp > 0) {
      if ((exp & 1) == 1) res = modMul(res, base, mod);
      base = modMul(base, base, mod);
      exp >>= 1;
    }
    return res;
  }

  static int modDiv(int a, int b, int mod) {
    return modMul(a, modPow(b, mod - 2, mod), mod);
  }

  static int gcd(int a, int b) {
    for (int t; b != 0; t = b, b = a % b, a = t);
    return a;
  }

  static int lowerBound(int[] arr, int target) {
    int lo = 0, hi = arr.length - 1, ans = -1;
    while (lo <= hi) {
      int mid = lo + (hi - lo) / 2;
      if (arr[mid] < target) {
        ans = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    return ans;
  }

  static long[] logSeries(long base, long target) {
    long sum = 0, p = 1;
    int cnt = 0;
    long[] res = new long[2];
    while (p < base) {
      sum += p;
      cnt++;
      if (sum == target) {
        res[0] = cnt;
        res[1] = sum;
        return res;
      }
      p *= 2;
    }
    res[0] = cnt;
    res[1] = sum;
    return res;
  }

  static void inc(Map<Integer, Integer> map, int key) {
    map.merge(key, 1, Integer::sum);
  }

  static long sumList(List<Long> list) {
    long total = 0;
    for (long x : list) total += x;
    return total;
  }

  static int toIndex(char c) {
    return c - 'a';
  }

  static int findIndex(int[] prefix, int start, int target) {
    int lo = start + 1, hi = prefix.length - 1, ans = 0;
    while (lo <= hi) {
      int mid = lo + (hi - lo) / 2;
      int diff = prefix[mid] - prefix[start];
      if (diff == target) return mid;
      if (diff < target) {
        ans = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    return ans;
  }

  static Pair<Long, Integer> process(List<Integer> nums) {
    long sum = 0;
    int minVal = Integer.MAX_VALUE;
    for (int x : nums) {
      sum += x;
      minVal = Math.min(minVal, x);
    }
    return new Pair<>(sum - minVal, minVal);
  }

  static int findMaxDivisor(Map<Integer, Integer> map, int n, int req) {
    int max = 0;
    for (int i = 1; i * i <= n; i++) {
      if (n % i == 0) {
        if (i != n / i) {
          if (map.getOrDefault(n / i, 0) == req) max = Math.max(max, n / i);
        }
        if (map.getOrDefault(i, 0) == req) max = Math.max(max, i);
      }
    }
    return max;
  }

  static List<Integer> getKeys(Map<Integer, Integer> map) {
    return new ArrayList<>(map.keySet());
  }

  static List<Integer> getValues(Map<Integer, Integer> map) {
    return new ArrayList<>(map.values());
  }

  static int getMax(List<Integer> list) {
    return list.stream().mapToInt(Integer::intValue).max().orElse(Integer.MIN_VALUE);
  }

  static int getMin(List<Integer> list) {
    return list.stream().mapToInt(Integer::intValue).min().orElse(Integer.MAX_VALUE);
  }

  static final int[][] DIRECTIONS = {{-1,0},{0,1},{1,0},{0,-1}};

  public static void main(String[] args) throws IOException {
    String s = br.readLine();
    int n = s.length();

    if (n == 1 && "0_X".indexOf(s.charAt(0)) >= 0) {
      bw.write("1\n");
    } else if (n == 1) {
      bw.write("0\n");
    } else if (s.charAt(0) == '0') {
      bw.write("0\n");
    } else {
      String[] valid = {"25", "50", "75", "00"};
      String[] patterns = {"__", "_X", "X_", "XX"};
      int[] base = {4, 4, 4, 1};
      base[1] = s.charAt(0) == 'X' ? 2 : 4;
      base[2] = s.charAt(0) == 'X' ? 3 : 4;
      base[0] = n == 2 ? 3 : 4;
      base[1] = n == 2 ? 3 : 4;

      int ways = 0;
      String tail = s.substring(n - 2);
      for (String v : valid) {
        if (tail.equals(v)) {
          ways = 1;
          break;
        }
      }

      if (ways == 0) {
        if (tail.charAt(0) == '_' || tail.charAt(0) == 'X') {
          ways = 2;
          if (tail.charAt(1) == '0' && s.charAt(0) == 'X') ways = 1;
        } else if (tail.charAt(1) == '_' || tail.charAt(1) == 'X') {
          ways = 1;
        } else {
          for (int i = 0; i < 4; i++) {
            if (tail.equals(patterns[i])) {
              ways = base[i];
              break;
            }
          }
        }
      }

      if (tail.equals("XX") && s.charAt(0) == 'X') ways = 0;

      if (ways > 0) {
        char c0 = tail.charAt(0), c1 = tail.charAt(1);
        if ("2570X_".indexOf(c0) < 0) ways = 0;
        if ("05X_".indexOf(c1) < 0) ways = 0;
      }

      int xways = 1;
      if (ways > 0) {
        if (tail.charAt(0) == 'X') xways = base[2];
        else if (tail.charAt(1) == 'X') xways = base[1] / 2;
        else xways = (s.charAt(0) == 'X') ? 9 : 10;
      }

      long mult = 1;
      boolean hasX = false;
      for (int i = 0; i < n - 2; i++) {
        if (s.charAt(i) == 'X') hasX = true;
        if (s.charAt(i) == '_') {
          mult *= (i == 0) ? 9 : 10;
        }
      }
      if (hasX && ways > 0) mult *= xways;
      mult *= ways;

      bw.write(Long.toString(mult) + "\n");
    }
    bw.flush();
  }
}
